import Header from "@/components/Header";
import Footer from "@/components/Footer";
import Link from "next/link";
import { getProjects } from "@/lib/projects";

export const revalidate = 60;

export default async function Home() {
  const projects = await getProjects();

  const hero =
    projects.find((project) => project.featured) ??
    projects.find((project) => project.cover_image) ??
    projects[0];

  return (
    <>
      <Header />

      {hero ? (
        <section className="hero">
          {hero.hero_image ? (
            <img
              src={hero.hero_image}
              alt={hero.title}
              className="hero-real-image"
            />
          ) : (
            <div className="hero-media" />
          )}

          <Link href={`/proyectos/${hero.slug}`} className="hero-label">
            {hero.title}
          </Link>

          <button className="hero-arrow left" type="button" aria-label="Proyecto anterior">
            ‹
          </button>
          <button className="hero-arrow right" type="button" aria-label="Proyecto siguiente">
            ›
          </button>
        </section>
      ) : (
        <section className="hero">
          <div className="hero-media" />
        </section>
      )}

      <section className="projects-section">
        <div className="container project-grid">
          {projects.map((project) => (
            <Link
              key={project.id}
              href={`/proyectos/${project.slug}`}
              className="project-card"
            >
              <div className="thumb">
                {project.sketch_image || project.cover_image ? (
                  <img
                    src={project.sketch_image ?? project.cover_image ?? ""}
                    alt={project.title}
                    className="project-card-image"
                  />
                ) : (
                  <span>⌂</span>
                )}
              </div>

              <div className="meta">
                <span>{project.title}</span>
              </div>
            </Link>
          ))}
        </div>
      </section>

      <Footer />

      <style>{`
        .hero-real-image{
          position:absolute;
          inset:0;
          width:100%;
          height:100%;
          object-fit:cover;
        }

        .project-card-image{
          width:100%;
          height:100%;
          object-fit:contain;
        }
      `}</style>
    </>
  );
}
